export function readAmount(raw: string) {
  const [whole, fraction = ''] = raw.trim().split(',');
  return Number(whole) * 100 + Number(fraction.padEnd(2, '0'));
}
export function formatAmount(cents: number) { return (cents / 100).toFixed(2); }

